// —— H 项（模型声明硬校验）+ L 项（team-config 成员覆盖档）共用的判定 ——
// 「合法模型口径」只在这两个纯函数里算一次，不许各处散抄；真正读档案
// （meta.json 拿团队名、teams/<name>/team.json、team/config.json）是 write 处理器层
// （opc.mjs 的 performOneWrite）的活——本文件保持纯函数风格，不碰文件系统。

// 派工登记（write dispatch）的特殊户头：底座级固定账户，模型不受团队名册约束——
//   主控＝壳会话自身（tick-begin 默认登记，见 opc.mjs／fire.mjs，这两处从不带 model）；
//   检察员＝验收人判条目走的独立强模型账户（opc-tick 剧本第三节「acceptance」）；
//   脚本＝fire 进程内直跑纯流程轮的零模型账户（fire.mjs 的机器验收轮，同样从不带 model）；
//   项目立项＝未派工用量的记账兜底桶名（ledger.mjs 入账时用，理论上不会经 write dispatch
//   落这个 employee 名，一并放行以防万一，不许把记账桶名反炒成一条写入规则漏洞）。
export const DISPATCH_SPECIAL_EMPLOYEES = new Set(['主控', '检察员', '脚本', '项目立项']);

// 团队名册按「谁」找成员：派工登记与团队流程实际落笔时，employee 字段有的写成员 id
//（剧本文档说的「成员 id」），有的写它的中文 name（e2e 演练全程如此，是本底座跑通过的真实用法）——
// 两条路都算「点名同一个人」，找成员时 id/name 都试，不逼死一种写法。
function findTeamMember(teamDoc, employee) {
  if (!Array.isArray(teamDoc?.members)) return undefined;
  return teamDoc.members.find((m) => m.id === employee || m.name === employee);
}

// 某个 employee 是不是当前团队名册里点了名的成员（id 或 name 命中，同 findTeamMember 的两条路）。
// 导出供 write dispatch 的 H 闸用：名册员工的新派工必须声明 model，不许借省略 model 字段免检溜过
//（「opus 领队没上场」的病根）。纯函数，teamDoc 靠参数传入、不读文件。
export function isTeamRosterMember(teamDoc, employee) {
  return findTeamMember(teamDoc, employee) !== undefined;
}

// 算出某个（非特殊户头）员工在当前团队 + 项目配置下，合法能报的模型档位清单——三个口径取并集：
//   ① team.json 里该成员的声明档（岗位定模型，不许临场换）；
//   ② team.json 的 escalation.upgrade_to（返工升档，全队通用，不分哪个成员）；
